import React, { useState } from 'react';

const QuanLyThongBaoCuDan = () => {
    const [activeTab, setActiveTab] = useState('chung');

    return (
        <div style={styles.container}>
            <header style={styles.header}>
                <h2 style={{color: '#2e7d32', display: 'flex', alignItems: 'center', gap: '10px'}}>🔔 Trung tâm thông báo</h2>
                <p style={{color: '#666'}}>Cập nhật những tin tức mới nhất từ Ban quản lý</p>
            </header>

            <div style={styles.tabContainer}>
                <button 
                    onClick={() => setActiveTab('chung')} 
                    style={{...styles.tab, borderBottom: activeTab === 'chung' ? '3px solid #2e7d32' : 'none', color: activeTab === 'chung' ? '#2e7d32' : '#888'}}
                >
                    Bảng tin tòa nhà
                </button>
                <button 
                    onClick={() => setActiveTab('rieng')} 
                    style={{...styles.tab, borderBottom: activeTab === 'rieng' ? '3px solid #2e7d32' : 'none', color: activeTab === 'rieng' ? '#2e7d32' : '#888'}}
                >
                    Phản hồi của tôi
                </button>
            </div>

            {activeTab === 'chung' ? (
                <div style={styles.newsCard}>
                    <span style={styles.newBadge}>MỚI</span>
                    <h4 style={{margin: '10px 0'}}>Thông báo cắt nước bảo trì định kỳ</h4>
                    <p style={styles.newsDate}>Đăng bởi: Ban Quản Lý | 17/04/2026</p>
                    <p style={styles.newsPreview}>Để phục vụ công tác bảo trì hệ thống nước sạch định kỳ, tòa nhà sẽ tạm ngưng cung cấp nước từ 8h00...</p>
                    <button style={styles.readMore}>Xem toàn bộ thông báo</button>
                </div>
            ) : (
                <div style={styles.formCard}>
                    <h3 style={{marginBottom: '20px'}}>Gửi ý kiến tới Admin</h3>
                    <textarea 
                        placeholder="Nhập nội dung phản hồi của bạn..." 
                        style={styles.textarea}
                    ></textarea>
                    <button style={styles.submitBtn}>Gửi phản hồi</button>
                </div>
            )}
        </div>
    );
};

const styles = {
    container: { width: '100%' },
    header: { marginBottom: '25px' },
    tabContainer: { display: 'flex', gap: '30px', borderBottom: '1px solid #ddd', marginBottom: '25px' },
    tab: { padding: '10px 5px', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '16px' },
    newsCard: { backgroundColor: '#fff', padding: '25px', borderRadius: '20px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', borderLeft: '5px solid #2e7d32' },
    newBadge: { backgroundColor: '#ff4d4f', color: '#fff', padding: '3px 10px', borderRadius: '5px', fontSize: '11px', fontWeight: 'bold' },
    newsDate: { fontSize: '12px', color: '#999', margin: '5px 0' },
    newsPreview: { color: '#444', lineHeight: '1.6' },
    readMore: { background: 'none', border: 'none', color: '#2e7d32', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px', padding: 0 },
    formCard: { backgroundColor: '#fff', padding: '30px', borderRadius: '20px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' },
    textarea: { width: '100%', height: '150px', padding: '15px', borderRadius: '12px', border: '1px solid #eee', backgroundColor: '#fafafa', marginBottom: '20px', resize: 'none', boxSizing: 'border-box' },
    submitBtn: { backgroundColor: '#2e7d32', color: '#fff', border: 'none', padding: '12px 30px', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold' }
};

export default QuanLyThongBaoCuDan;
